import { useState, useEffect, useRef, useMemo, useGrokTheme, CSSProperties, ChangeEvent, KeyboardEvent } from "grok/canvas";

/* =============================================================================
 * EVENT TRACKER PAGE: shareable kit version (contains NO data)
 * -----------------------------------------------------------------------------
 * Five tabs: Picks · Calendar · Save for later · History · Budget, plus a
 * detail drawer and help dialog. Everything below the data block is the
 * real design. Do not edit it to add data.
 *
 * HOW A BOT INJECTS ITS OWN DATA
 * 1. Build a JSON object shaped like `PageData` (types below). The easiest way:
 *      python3 scripts/build_page_payload.py --data-dir /workspace/events \
 *        --page page/tracker.canvas.tsx --out /workspace/events/tracker.canvas.tsx
 *    The script reads events.json, annual_calendar.json, history.json,
 *    budget.json, preferences.json and setup-state.json (top_ids), maps them
 *    to the shapes below, and replaces ONLY the text between the two marker
 *    lines `@@PAGE_DATA_START@@` and `@@PAGE_DATA_END@@`.
 * 2. Exact constant name: `PAGE_DATA` (type `PageData`). It must stay a
 *    single `const PAGE_DATA: PageData = <JSON>;` statement between the markers.
 * 3. Pass the resulting file to WriteCanvas (create once, then overwrite or
 *    EditCanvas the SAME Page on later refreshes).
 *
 * Shape (all fields required; use null / [] when unknown, never fake values):
 *   preferences: { bot_name, page_eyebrow, city, timezone (IANA), tz_label
 *                  (e.g. "PT"), currency (ISO), nightly_label (e.g. "9pm"),
 *                  free_windows_label }
 *   as_of:       "YYYY-MM-DD" snapshot date in the owner's zone, or null
 *   events:      Event[]   (see type Event; lo/hi = listed price range)
 *   annual:      Annual[]  (see type Annual)
 *   top_ids:     string[]  max 3 ids from the latest real recommendation
 *   history:     { entries: HistoryEntry[] }
 *   budget:      Budget    (nulls render as "not set", never as 0)
 * Empty data renders empty states on every tab.
 * ========================================================================== */

type Pricing = { best_price:number|null; best_source:string|null; best_url:string|null; face_value:number|null; conditions:string|null; deadline:string|null; verified_at:string|null; confidence:string|null; notes:string|null; availability?:string|null };
type Event = { id:string; name:string; date:string; time:string; end?:string; venue:string; category:string; lo:number|null; hi:number|null; url:string; short:string; why:string; sessions?:{date:string;time:string}[]; pricing?:Pricing|null; availability?:string; on_call_ok?:boolean; run?:string };
type Annual = { id:string; name:string; date_start:string|null; timing:string; category:string; price_min:number|null; price_max:number|null; price_basis:string|null; worth_splurge:boolean; best_free:boolean; url:string; dates_confirmed:boolean; note?:string|null };
type HistoryEntry = {event_id:string;status:string;date:string;event_date?:string|null;actual_spend?:number|null;amount_spent?:number|null;event_name?:string|null;worth_it?:string|null;feedback_notes?:string|null;decline_reason?:string|null};
type Budget = { budget_year_start:string|null; budget_year_end:string|null; currency:string; annual_budget:number|null; per_event_max:number|null; baseline_spend:number|null; events_per_month_cap:number|null; cap_counts_free_events:boolean|null; scope:string|null };
type Preferences = { bot_name:string|null; page_eyebrow:string|null; city:string|null; timezone:string; tz_label:string; currency:string; nightly_label:string|null; free_windows_label:string|null };
type PageData = { preferences:Preferences; as_of:string|null; events:Event[]; annual:Annual[]; top_ids:string[]; history:{entries:HistoryEntry[]}; budget:Budget };

// @@PAGE_DATA_START@@ (generated by scripts/build_page_payload.py; replace everything between the markers)
const PAGE_DATA:PageData = {"preferences":{"bot_name":null,"page_eyebrow":null,"city":null,"timezone":"America/Los_Angeles","tz_label":"PT","currency":"USD","nightly_label":"9pm","free_windows_label":null},"as_of":null,"events":[],"annual":[],"top_ids":[],"history":{"entries":[]},"budget":{"budget_year_start":null,"budget_year_end":null,"currency":"USD","annual_budget":null,"per_event_max":null,"baseline_spend":null,"events_per_month_cap":null,"cap_counts_free_events":null,"scope":null}};
// @@PAGE_DATA_END@@

const P = PAGE_DATA.preferences;
const TZ = P.timezone || "America/Los_Angeles";
const TZ_LABEL = P.tz_label || "";
const EVENTS:Event[] = PAGE_DATA.events;
const ANNUAL:Annual[] = PAGE_DATA.annual;
const BUDGET:Budget = PAGE_DATA.budget;
const HISTORY:{entries:HistoryEntry[]} = PAGE_DATA.history || {entries:[]};
function todayInZone():string {try{return new Intl.DateTimeFormat("en-CA",{timeZone:TZ,year:"numeric",month:"2-digit",day:"2-digit"}).format(new Date());}catch{return new Date().toISOString().slice(0,10);}}
const AS_OF = PAGE_DATA.as_of || todayInZone();
function historyEventDate(h:HistoryEntry):string {return (h.event_date || EVENTS.find((e:Event)=>e.id===h.event_id)?.date || h.date).slice(0,10);}
const latestHistory = new Map<string,HistoryEntry>();
HISTORY.entries.slice().sort((a:HistoryEntry,b:HistoryEntry)=>a.date.localeCompare(b.date)).forEach((h:HistoryEntry)=>latestHistory.set(h.event_id,h));
const LATEST:HistoryEntry[] = Array.from(latestHistory.values()).sort((a:HistoryEntry,b:HistoryEntry)=>b.date.localeCompare(a.date));
const acceptedHistory = LATEST.filter((h:HistoryEntry)=>["accepted","booked","attended"].includes(h.status));
const inBudgetYear = (d:string)=>(!BUDGET.budget_year_start||d>=BUDGET.budget_year_start)&&(!BUDGET.budget_year_end||d<=BUDGET.budget_year_end);
const budgetHistory = acceptedHistory.filter((h:HistoryEntry)=>inBudgetYear(historyEventDate(h)));
const BASELINE_KNOWN = BUDGET.baseline_spend!==null&&BUDGET.baseline_spend!==undefined;
const SPENT = (BUDGET.baseline_spend??0) + budgetHistory.reduce((sum:number,h:HistoryEntry)=>sum+(h.actual_spend??h.amount_spent??0),0);
const TARGET = BUDGET.annual_budget;
const REMAINING:number|null = TARGET===null||TARGET===undefined?null:TARGET-SPENT;
const DAYS_LEFT:number|null = BUDGET.budget_year_end?Math.max(0,Math.round((Date.parse(BUDGET.budget_year_end+"T00:00:00Z")-Date.parse(AS_OF+"T00:00:00Z"))/86400000)+1):null;
const MONTH_USED = acceptedHistory.filter((h:HistoryEntry)=>historyEventDate(h).slice(0,7)===AS_OF.slice(0,7)).length;
const CAP = BUDGET.events_per_month_cap;
const TOP_IDS:string[] = (PAGE_DATA.top_ids||[]).slice(0,3);
const MONTHS = ["January","February","March","April","May","June","July","August","September","October","November","December"];
const CATEGORIES = ["All",...Array.from(new Set(EVENTS.map((e:Event)=>e.category).filter(Boolean))).sort()];
const TABS = [{id:"Picks",icon:"spark"},{id:"Calendar",icon:"calendar"},{id:"Save for later",icon:"bookmark"},{id:"History",icon:"history"},{id:"Budget",icon:"budget"}];
function usd(n:number|null|undefined):string {if(n===null||n===undefined)return "TBD";const c=P.currency||"USD";try{return n.toLocaleString("en-US",{style:"currency",currency:c,maximumFractionDigits:2,minimumFractionDigits:Number.isInteger(n)?0:2});}catch{return "$"+n.toLocaleString("en-US",{maximumFractionDigits:2});}}
function range(lo:number|null,hi:number|null):string {if(lo===null)return hi===null?"Price unknown":"Up to "+usd(hi);return hi===null?(lo===0?"Free options; paid varies":usd(lo)+"+"):lo===hi?usd(lo):usd(lo)+"–"+usd(hi);}
function price(e:Event):number|null {return e.pricing?.best_price ?? e.lo ?? null;}
function priceSource(e:Event):string {return e.pricing?.best_url || e.url;}
function priceLabel(e:Event):string {return e.pricing?.confidence==="unverified"?"Unverified price":"Best found";}
function pricingAlert(e:Event):string {const a=e.pricing?.availability;return a==="sold_out"?"Online sold out; door availability unconfirmed.":a==="waitlist"?"Waitlist only.":"";}
function level(n:number|null):string {return n===null?"Unknown":n===0?"$0":n<=25?"$":n<=75?"$$":n<=300?"$$$":">$300";}
function clock(s:string):string {if(!s)return "Time TBD";let h=Number(s.slice(0,2));return (h%12||12)+(s.slice(3)==="00"?"":":"+s.slice(3))+(h<12?"am":"pm");}
function date(s:string):string {return new Date(s+"T12:00:00Z").toLocaleDateString("en-US",{timeZone:"UTC",weekday:"short",month:"short",day:"numeric"});}
function longDate(s:string|null):string {return s?new Date(s+"T12:00:00Z").toLocaleDateString("en-US",{timeZone:"UTC",month:"short",day:"numeric",year:"numeric"}):"not set";}
function weekend(s:string):boolean {const d=new Date(s+"T12:00:00Z").getUTCDay();return d===0||d===6;}
function annualGroup(a:Annual):string {if(a.date_start)return a.date_start.slice(0,7);for(let i=0;i<12;i++)if(a.timing.includes(MONTHS[i]))return "typical-"+String(i+1).padStart(2,"0");return "recurring";}
function groupLabel(k:string):string {if(k==="recurring")return "Year-round";if(k.startsWith("typical"))return MONTHS[Number(k.slice(-2))-1]+" · typical";return MONTHS[Number(k.slice(5,7))-1]+" "+k.slice(0,4);}
function isAnnual(x:Event|Annual):x is Annual {return (x as Annual).timing!==undefined;}
function Glyph({kind,size=24}:{kind:string;size?:number}) {
 const k=kind.toLowerCase();
 let path="M12 3l2.6 6.4L21 12l-6.4 2.6L12 21l-2.6-6.4L3 12l6.4-2.6Z";
 if(k.includes("calendar"))path="M5 5h14v15H5z M8 3v4 M16 3v4 M5 10h14 M8 13h2 M14 13h2 M8 17h2";
 else if(k.includes("bookmark"))path="M6 3h12v18l-6-4-6 4z";
 else if(k.includes("history"))path="M4 8a9 9 0 1 1 0 9 M3 3v6h6 M12 7v5l3 2";
 else if(k.includes("budget"))path="M3 6h18v14H3z M3 6l14-3v3 M15 12h6v5h-6z M17 14h1";
 else if(k.includes("music"))path="M9 17V5l11-2v12 M9 9l11-2 M9 17c0 3-6 4-6 1s6-4 6-1 M20 15c0 3-6 4-6 1s6-4 6-1";
 else if(k.includes("performance")||k.includes("dance")||k.includes("theater")||k.includes("comedy"))path="M4 4q8 4 16 0v7q-1 9-8 11-7-2-8-11z M7 10h2 M15 10h2 M8 15q4 4 8 0";
 else if(k.includes("art")||k.includes("design"))path="M12 3c-5 0-9 4-9 9s4 9 9 9c3 0 1-4 4-4h2c5 0 4-14-6-14z M7 10h.1 M10 6h.1 M15 7h.1 M18 11h.1";
 else if(k.includes("film")||k.includes("ideas")||k.includes("book"))path="M4 4h16v16H4z M8 4v16 M16 4v16 M4 8h4 M4 15h4 M16 8h4 M16 15h4 M11 9l3 3-3 3z";
 else if(k.includes("outdoors")||k.includes("fitness")||k.includes("sports"))path="M2 20L9 7l4 7 3-5 6 11z M7 11l2 2 2-2 M17 3h.1";
 else if(k.includes("tech")||k.includes("science"))path="M7 7h10v10H7z M10 2v5 M14 2v5 M10 17v5 M14 17v5 M2 10h5 M2 14h5 M17 10h5 M17 14h5";
 return <svg width={size} height={size} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true"><path d={path}/></svg>;
}

export default function App(){
 const t=useGrokTheme();
 const [tab,setTab]=useState<string>("Picks");
 const [query,setQuery]=useState<string>("");
 const [cat,setCat]=useState<string>("All");
 const [cost,setCost]=useState<string>("Any");
 const [day,setDay]=useState<string>("Any day");
 const [free,setFree]=useState<boolean>(false);
 const [browse,setBrowse]=useState<boolean>(false);
 const [month,setMonth]=useState<string>(AS_OF.slice(0,7));
 const [chosenDay,setChosenDay]=useState<string>(AS_OF);
 const [selected,setSelected]=useState<Event|Annual|null>(null);
 const [help,setHelp]=useState<boolean>(false);
 const drawer=useRef<HTMLDivElement>(null);
 const closeButton=useRef<HTMLButtonElement>(null);
 const lastFocus=useRef<HTMLElement|null>(null);
 useEffect(()=>{if(selected||help){lastFocus.current=document.activeElement as HTMLElement;closeButton.current?.focus();return ()=>{lastFocus.current?.focus();};}},[selected,help]);
 const vars={"--paper":t.bg.base,"--subtle":t.bg.subtle,"--elevated":t.bg.elevated,"--ink":t.text.primary,"--muted":t.text.secondary,"--quiet":t.text.tertiary,"--line":t.border.default,"--line-soft":t.border.subtle,"--accent":t.dataviz.categorical[0],"--tint":t.fill.accentSubtle,"--hover":t.fill.hover,fontFamily:t.font.family,color:t.text.primary,background:t.bg.base} as CSSProperties;
 const filtered=useMemo(()=>EVENTS.filter((e:Event)=>(cat==="All"||e.category===cat)&&(cost==="Any"||level(price(e))===cost)&&(!free||price(e)===0)&&(day==="Any day"||(day==="Weekend"?weekend(e.date):!weekend(e.date)&&e.time>="17:00"))&&(e.name+" "+(e.venue||"")).toLowerCase().includes(query.toLowerCase())),[cat,cost,day,free,query]);
 const picks=(browse?filtered:TOP_IDS.map((id:string)=>filtered.find((e:Event)=>e.id===id)).filter((e:Event|undefined):e is Event=>!!e));
 const occurrences=useMemo(()=>filtered.flatMap((e:Event)=>(e.sessions||[{date:e.date,time:e.time}]).map((s:{date:string;time:string})=>({event:e,date:s.date,time:s.time}))),[filtered]);
 const dayEvents=occurrences.filter((o:{event:Event;date:string;time:string})=>o.date===chosenDay);
 const monthYear=Number(month.slice(0,4)), monthIndex=Number(month.slice(5,7))-1;
 const startDay=new Date(Date.UTC(monthYear,monthIndex,1)).getUTCDay();
 const daysInMonth=new Date(Date.UTC(monthYear,monthIndex+1,0)).getUTCDate();
 const cells=Array.from({length:Math.ceil((startDay+daysInMonth)/7)*7},(_:unknown,i:number)=>i-startDay+1);
 const annualFiltered=ANNUAL.filter((a:Annual)=>(a.name+" "+a.category).toLowerCase().includes(query.toLowerCase())&&(!free||a.price_max===0));
 const annualGroups=Array.from(new Set(annualFiltered.map((a:Annual)=>annualGroup(a)))).sort((a:string,b:string)=>a.localeCompare(b));
 function shiftMonth(delta:number){const d=new Date(Date.UTC(monthYear,monthIndex+delta,1));setMonth(d.toISOString().slice(0,7));setChosenDay(d.toISOString().slice(0,10));}
 function tabKey(e:KeyboardEvent<HTMLButtonElement>,id:string){const i=TABS.findIndex((x:{id:string;icon:string})=>x.id===id);let next=i;if(e.key==="ArrowRight")next=(i+1)%TABS.length;else if(e.key==="ArrowLeft")next=(i+TABS.length-1)%TABS.length;else if(e.key==="Home")next=0;else if(e.key==="End")next=TABS.length-1;else return;e.preventDefault();setTab(TABS[next].id);setQuery("");document.getElementById("tab-"+TABS[next].id.replaceAll(" ","-"))?.focus();}
 function keyTrap(e:KeyboardEvent<HTMLDivElement>){if(e.key==="Escape"){setSelected(null);setHelp(false);}if(e.key==="Tab"){const els=drawer.current?.querySelectorAll<HTMLElement>('button,a[href],input,select,[tabindex="0"]');if(!els?.length)return;const first=els[0],last=els[els.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}}
 function card(e:Event,compact=false){return <button key={e.id} className={"event-card "+(compact?"compact":"")} onClick={()=>setSelected(e)} aria-label={"Details for "+e.name}>
  <div className="event-art"><div className="date-chip"><strong>{Number(e.date.slice(-2))}</strong><span>{MONTHS[Number(e.date.slice(5,7))-1].slice(0,3)}</span></div><div className="art-icon"><Glyph kind={e.category} size={72}/></div><span className="price-chip">{price(e)===0?"$0":price(e)===null?"Price TBD":usd(price(e))+"+"}</span><span className="category">{e.category}</span></div>
  <div className="card-content"><h3>{e.name}</h3><div className="event-time">{date(e.date)} · {clock(e.time)} {TZ_LABEL}</div><div className="venue" title={e.venue}>{e.venue}</div><div className="short">{e.short}</div>{e.pricing&&<div className="deal" title={[e.pricing.best_source,e.pricing.conditions,e.pricing.notes].filter(Boolean).join(" · ")}><div>{priceLabel(e)} · {usd(price(e))}{e.pricing.face_value!==null&&price(e)!==null&&e.pricing.face_value>(price(e) as number)?" / "+usd(e.pricing.face_value)+" standard":""}</div><div className="deal-source">{e.pricing.best_source}</div>{pricingAlert(e)&&<div className="price-alert">{pricingAlert(e)}</div>}</div>}{e.on_call_ok!==undefined&&<div className="short">{e.on_call_ok?"On-call OK":"Not on-call suitable"}</div>}{e.availability&&<div className="short">{e.availability}</div>}</div>
 </button>;}
 const selectedEvent=selected&&!isAnnual(selected)?selected:null;
 const selectedAnnual=selected&&isAnnual(selected)?selected:null;
 return <div className="event-app" style={vars}>
 <style>{`
 .event-app{height:calc(100dvh - 48px);max-height:900px;min-height:0;display:flex;flex-direction:column;overflow:hidden;position:relative;border:1px solid var(--line);border-radius:16px;box-sizing:border-box;font-size:14px;color:var(--ink);background:var(--paper)}
 .event-app *{box-sizing:border-box}.event-app button,.event-app input{font:inherit;color:inherit}.event-app button{cursor:pointer}.event-app button:focus-visible,.event-app a:focus-visible,.event-app input:focus-visible{outline:2px solid var(--accent);outline-offset:3px}.event-app button:disabled{cursor:default;opacity:.5}.event-app a{color:var(--ink);text-underline-offset:4px}.event-app h1,.event-app h2,.event-app h3,.event-app p{margin:0}.event-app h2{font-size:24px;letter-spacing:-.6px}.topbar{display:flex;align-items:center;justify-content:space-between;padding:16px 24px;gap:16px;flex-shrink:0;border-bottom:1px solid var(--line-soft)}.brand{display:flex;align-items:center;gap:12px;min-width:0}.brand-mark{display:flex;align-items:center;color:var(--ink)}.brand h1{font-size:18px;letter-spacing:-.4px}.eyebrow{font-size:11px;letter-spacing:1.6px;text-transform:uppercase;color:var(--quiet);margin-bottom:3px}.top-meta{display:flex;align-items:center;gap:16px;color:var(--muted);font-size:12px}.icon-button{border:1px solid var(--line);background:var(--paper);border-radius:8px;min-width:36px;min-height:36px;display:inline-flex;align-items:center;justify-content:center;padding:8px}.nav{display:flex;flex-wrap:wrap;gap:8px;padding:8px 24px;border-bottom:1px solid var(--line-soft);flex-shrink:0;background:var(--paper)}.nav button{display:flex;align-items:center;gap:8px;border:0;background:transparent;border-radius:8px;padding:10px 16px;font-size:13px;color:var(--muted)}.nav button[aria-selected=true]{background:var(--tint);color:var(--ink);box-shadow:inset 0 -2px var(--accent)}.main{flex:1;min-height:0;overflow:hidden;display:flex;flex-direction:column;padding:24px;gap:16px}.section-head{display:flex;justify-content:space-between;align-items:center;gap:16px;flex-shrink:0;flex-wrap:wrap}.section-head .sub{font-size:12px;color:var(--muted);margin-top:4px}.head-actions{display:flex;gap:8px;align-items:center;flex-wrap:wrap}.pill{border:1px solid var(--line);border-radius:999px;background:var(--paper);padding:7px 12px;font-size:12px;display:inline-flex;align-items:center;gap:6px}.pill[aria-pressed=true]{background:var(--tint);border-color:var(--accent)}.filters{display:flex;gap:8px;align-items:center;flex-wrap:wrap;flex-shrink:0}.filter-group{display:flex;gap:4px;align-items:center;flex-wrap:wrap}.search{display:flex;align-items:center;border:1px solid var(--line);border-radius:8px;min-width:0;flex:1 1 160px;max-width:280px;padding:0 12px;height:36px;background:var(--paper)}.search input{border:0;background:transparent;outline:none;min-width:0;width:100%;font-size:12px}.filters details{position:relative}.filters summary{list-style:none;cursor:pointer}.popover{position:absolute;top:42px;left:0;z-index:5;display:flex;flex-wrap:wrap;gap:6px;width:232px;padding:12px;border:1px solid var(--line);border-radius:12px;background:var(--elevated);box-shadow:0 8px 32px color-mix(in srgb,var(--ink) 10%,transparent)}.scroll-panel{flex:1;min-height:0;overflow:auto;overscroll-behavior:contain;padding:2px 3px 16px}.cards{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:24px;align-content:start}.event-card{padding:0;text-align:left;overflow:hidden;background:var(--paper);border:1px solid var(--line);border-radius:16px;transition:transform .18s,box-shadow .18s;min-width:0;align-self:start}.event-card:hover{transform:translateY(-3px);box-shadow:0 10px 28px color-mix(in srgb,var(--ink) 8%,transparent)}.event-art{height:160px;position:relative;background:var(--tint);overflow:hidden;border-bottom:1px solid var(--line-soft)}.art-icon{position:absolute;inset:0;display:flex;align-items:center;justify-content:center;color:var(--accent);opacity:.8;transform:rotate(-9deg)}.date-chip{position:absolute;top:16px;left:16px;border-radius:10px;padding:8px 12px;background:var(--paper);border:1px solid var(--line-soft);display:flex;flex-direction:column;align-items:center;z-index:1;line-height:1}.date-chip strong{font-size:28px;letter-spacing:-1px}.date-chip span{font-size:10px;letter-spacing:1px;margin-top:5px;color:var(--muted);text-transform:uppercase}.price-chip{position:absolute;top:16px;right:16px;background:var(--paper);border:1px solid var(--line-soft);padding:7px 10px;border-radius:999px;font-size:12px;font-weight:600}.category{position:absolute;bottom:12px;left:16px;font-size:11px;letter-spacing:1px;text-transform:uppercase;color:var(--muted)}.card-content{padding:16px;display:flex;flex-direction:column;gap:8px}.card-content h3{font-size:18px;line-height:1.25;letter-spacing:-.4px;min-height:45px;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden}.event-time{font-size:12px;font-weight:500}.venue{font-size:12px;color:var(--muted);overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.short{font-size:12px;color:var(--muted);line-height:1.4}.deal{font-size:11px}.footer{flex-shrink:0;padding:10px 24px;border-top:1px solid var(--line-soft);font-size:10px;color:var(--quiet);display:flex;justify-content:space-between;gap:8px;flex-wrap:wrap}.footer button{border:0;background:transparent;font-size:10px;text-decoration:underline;padding:0}.empty{height:100%;min-height:80px;display:flex;align-items:center;justify-content:center;gap:12px;color:var(--muted);font-size:13px;text-align:center}.calendar-layout{flex:1;min-height:0;display:grid;grid-template-columns:minmax(0,1.7fr) minmax(220px,1fr);gap:24px}.month-wrap{display:flex;flex-direction:column;min-height:0}.week-head{display:grid;grid-template-columns:repeat(7,minmax(0,1fr));font-size:11px;color:var(--quiet);text-align:center;padding-bottom:8px}.month-grid{display:grid;grid-template-columns:repeat(7,minmax(0,1fr));flex:1;min-height:0;gap:4px}.day{position:relative;display:flex;flex-direction:column;align-items:flex-start;padding:8px;min-width:0;border:1px solid var(--line-soft);border-radius:8px;background:var(--paper);overflow:hidden}.day.weekend{background:var(--subtle)}.day.evening:after{content:'';height:15%;position:absolute;bottom:0;left:0;right:0;background:var(--subtle);pointer-events:none}.day[aria-pressed=true]{border:2px solid var(--accent);padding:7px}.day.blank{border-color:transparent;background:transparent}.day-num{font-size:12px;z-index:1}.day.today .day-num{font-weight:700;text-decoration:underline;text-underline-offset:4px}.dots{display:flex;flex-wrap:wrap;gap:3px;margin-top:auto;z-index:1}.dot{width:6px;height:6px;background:var(--accent);border-radius:50%}.day-count{font-size:9px;color:var(--quiet);margin-top:4px;z-index:1}.day-panel{border-left:1px solid var(--line-soft);padding-left:24px;min-height:0;overflow:auto;overscroll-behavior:contain}.day-panel h3{font-size:15px;margin-bottom:16px}.day-event{width:100%;border:1px solid var(--line);background:var(--paper);border-radius:12px;padding:12px;display:flex;gap:12px;text-align:left;margin-bottom:12px;align-items:center}.day-event strong{font-size:13px;line-height:1.3;display:block}.day-event small{color:var(--muted);font-size:11px;display:block;margin-top:6px}.mini-glyph{display:flex;padding:10px;border-radius:8px;background:var(--tint);color:var(--accent)}.timeline{flex:1;min-height:0;overflow:auto;overscroll-behavior:contain;display:flex;gap:24px;padding:8px 4px 20px;scroll-snap-type:x proximity;align-items:flex-start}.month-column{flex:0 0 min(272px,82vw);min-width:0;scroll-snap-align:start}.month-label{display:flex;align-items:center;gap:8px;font-size:12px;font-weight:600;padding-bottom:16px;border-bottom:2px solid var(--line);margin-bottom:16px}.month-label:before{content:'';width:8px;height:8px;border-radius:50%;background:var(--accent)}.annual-card{width:100%;display:flex;align-items:flex-start;gap:12px;text-align:left;background:var(--paper);padding:16px;border:1px solid var(--line);border-radius:12px;margin-bottom:12px}.annual-card strong{font-size:14px;line-height:1.35;display:block}.annual-card small{display:block;font-size:11px;color:var(--muted);margin-top:8px}.annual-price{font-size:14px;font-weight:600;margin-top:12px}.budget-panel{flex:1;min-height:0;overflow:auto;display:flex;align-items:center;justify-content:center;gap:48px;flex-wrap:wrap;padding:24px}.ring{width:min(100%,320px);flex-shrink:1}.budget-facts{display:grid;gap:24px;min-width:180px}.budget-facts strong{display:block;font-size:28px;letter-spacing:-1px}.budget-facts span{display:block;margin-top:4px;font-size:12px;color:var(--muted)}.overlay{position:absolute;inset:0;z-index:20;background:color-mix(in srgb,var(--ink) 16%,transparent);display:flex;justify-content:flex-end;backdrop-filter:blur(3px)}.drawer{height:100%;width:min(100%,440px);background:var(--paper);border-left:1px solid var(--line);display:flex;flex-direction:column;box-shadow:-16px 0 48px color-mix(in srgb,var(--ink) 10%,transparent);min-height:0}.drawer-top{padding:16px 24px;display:flex;justify-content:space-between;align-items:center;border-bottom:1px solid var(--line-soft);font-size:11px;color:var(--muted);flex-shrink:0}.drawer-body{overflow:auto;padding:24px;display:flex;flex-direction:column;gap:24px;flex:1;min-height:0}.drawer-art{height:120px;background:var(--tint);display:flex;align-items:center;justify-content:center;color:var(--accent);border-radius:12px}.drawer h2{font-size:25px;line-height:1.15}.drawer dl{margin:0;display:grid;grid-template-columns:64px minmax(0,1fr);gap:16px;font-size:13px;line-height:1.5}.drawer dt{color:var(--muted);font-size:11px}.drawer dd{margin:0}.drawer p{font-size:13px;line-height:1.6;color:var(--muted)}.drawer .source-link{font-size:12px;overflow-wrap:anywhere}.drawer .detail-label{font-size:10px;text-transform:uppercase;letter-spacing:1px;color:var(--quiet);margin-bottom:8px}.drawer .primary-link{display:flex;justify-content:center;padding:12px 16px;border:1px solid var(--line);border-radius:8px;text-decoration:none;font-weight:600;font-size:13px;background:var(--tint)}
 .deal-source{font-size:10px;color:var(--quiet);overflow:hidden;text-overflow:ellipsis;white-space:nowrap;margin-top:4px}.price-alert{font-size:11px;color:var(--muted);margin-top:6px}.budget-dots{display:flex;gap:8px;flex-wrap:wrap;margin-top:12px}.budget-dot{width:16px;height:16px;border-radius:50%;border:1px solid var(--line);background:var(--subtle)}.budget-dot.used{background:var(--accent);border-color:var(--accent)}.budget-limit{font-size:12px;color:var(--muted);padding-top:8px}.pricing-conditions{font-size:12px;line-height:1.5;color:var(--muted);margin-top:12px}
 .filters{position:relative}.filters details{position:static}.filters .popover{top:calc(100% + 8px);left:0;width:min(264px,100%)}
 @media(prefers-reduced-motion:reduce){.event-card{transition:none}.event-card:hover{transform:none}}
 @media(max-width:900px){.topbar,.nav{padding-left:16px;padding-right:16px}.main{padding:16px}.cards{gap:16px}.event-art{height:136px}.art-icon svg{width:56px;height:56px}.date-chip{left:12px;top:12px;padding:7px 10px}.price-chip{right:12px;top:12px}.card-content{padding:12px}.card-content h3{font-size:16px;min-height:40px}.calendar-layout{gap:16px;grid-template-columns:minmax(0,1.5fr) minmax(180px,1fr)}.day-panel{padding-left:16px}.top-meta .snapshot{display:none}.day{padding:5px}.day[aria-pressed=true]{padding:4px}.day-count{display:none}.budget-panel{gap:24px}}
 @media(max-width:640px){.event-app{height:calc(100dvh - 24px);max-height:none;border-radius:12px}.topbar{padding:12px 16px;order:0}.brand h1{font-size:15px}.eyebrow{font-size:9px}.top-meta .nightly{display:none}.nav{order:4;padding:8px 4px calc(8px + env(safe-area-inset-bottom));border-bottom:0;border-top:1px solid var(--line);gap:0;justify-content:space-around}.nav button{flex:1 1 0;min-width:0;padding:6px 2px;flex-direction:column;gap:5px;font-size:9px;border-radius:6px}.nav button svg{width:20px;height:20px}.main{order:1;padding:16px;gap:12px}.footer{order:3;padding:8px 16px;font-size:9px}.footer .footer-extra{display:none}.section-head h2{font-size:22px}.cards{grid-template-columns:1fr;gap:16px}.event-art{height:152px}.card-content h3{min-height:0;font-size:18px}.filters{gap:6px}.search{max-width:none;flex-basis:100%}.pill{padding:6px 9px;font-size:11px}.calendar-layout{display:flex;flex-direction:column;gap:12px;overflow:auto}.month-wrap{flex:0 0 290px}.day-panel{border-left:0;border-top:1px solid var(--line);padding:16px 0 0;flex:1;min-height:120px;overflow:auto}.day{min-height:35px}.day-panel h3{margin-bottom:12px}.day-event{padding:10px;margin-bottom:8px}.month-column{flex-basis:80%}.budget-panel{align-content:center;padding:0;gap:16px}.ring{width:min(100%,240px)}.budget-facts{display:flex;gap:24px;min-width:0;flex-wrap:wrap;justify-content:center}.budget-facts strong{font-size:22px}.budget-facts span{font-size:10px}.drawer-top{padding:12px 16px}.drawer-body{padding:20px}.section-head .sub{font-size:11px}}
 `}</style>
 <header className="topbar"><div className="brand"><span className="brand-mark"><Glyph kind="spark" size={28}/></span><div><div className="eyebrow">{P.page_eyebrow||P.city||"Your city"}</div><h1>Event Tracker</h1></div></div><div className="top-meta"><span className="snapshot">{PAGE_DATA.as_of?longDate(PAGE_DATA.as_of):"No data yet"} · {TZ_LABEL}</span><span className="nightly">0–3 picks · {P.nightly_label||"nightly"}</span><button className="icon-button" aria-label="How this works" title="Decisions and feedback stay in chat" onClick={()=>setHelp(true)}>?</button></div></header>
 <nav className="nav" role="tablist" aria-label="Event tracker views">{TABS.map((x:{id:string;icon:string})=><button key={x.id} role="tab" id={"tab-"+x.id.replaceAll(" ","-")} aria-selected={tab===x.id} aria-controls="active-view" tabIndex={tab===x.id?0:-1} onKeyDown={(e:KeyboardEvent<HTMLButtonElement>)=>tabKey(e,x.id)} onClick={()=>{setTab(x.id);setQuery("");}}><Glyph kind={x.icon} size={18}/><span>{x.id}</span></button>)}</nav>
 <main className="main" id="active-view" role="tabpanel" aria-labelledby={"tab-"+tab.replaceAll(" ","-")}>
 {tab==="Picks"&&<><div className="section-head"><div><h2>{browse?"Explore":"Next up"}</h2><div className="sub">{browse?EVENTS.length+" curated candidates":"Quality over quantity · up to three"}</div></div><div className="head-actions"><button className="pill" aria-pressed={!browse} onClick={()=>setBrowse(false)}>Top picks</button><button className="pill" aria-pressed={browse} onClick={()=>setBrowse(true)}>Explore {EVENTS.length}</button></div></div></>}
 {tab==="Calendar"&&<div className="section-head"><div><h2>{MONTHS[monthIndex]} {monthYear}</h2><div className="sub" title="Shading shows your stated preferences only, not confirmed calendar availability.">{P.free_windows_label||"Weekends + weekday evenings shaded"}</div></div><div className="head-actions"><button className="icon-button" aria-label="Previous month" onClick={()=>shiftMonth(-1)}>‹</button><button className="pill" onClick={()=>{setMonth(AS_OF.slice(0,7));setChosenDay(AS_OF);}}>Today</button><button className="icon-button" aria-label="Next month" onClick={()=>shiftMonth(1)}>›</button></div></div>}
 {(tab==="Picks"||tab==="Calendar")&&<div className="filters"><div className="search"><input aria-label="Search events" placeholder="Search events or venues" value={query} onChange={(e:ChangeEvent<HTMLInputElement>)=>setQuery(e.target.value)}/></div><details><summary className="pill">{cat==="All"?"Category":cat} ⌄</summary><div className="popover">{CATEGORIES.map((c:string)=><button className="pill" key={c} aria-pressed={cat===c} onClick={()=>setCat(c)}>{c}</button>)}</div></details><details><summary className="pill" title="$ up to $25; $$ up to $75; $$$ up to $300, based on lowest listed or best-found price">{cost==="Any"?"Cost":cost} ⌄</summary><div className="popover">{["Any","$0","$","$$","$$$",">$300","Unknown"].map((c:string)=><button className="pill" key={c} aria-pressed={cost===c} onClick={()=>setCost(c)}>{c}</button>)}</div></details><button className="pill" aria-pressed={day==="Weekday eve"} onClick={()=>setDay(day==="Weekday eve"?"Any day":"Weekday eve")}>Weekday eve</button><button className="pill" aria-pressed={day==="Weekend"} onClick={()=>setDay(day==="Weekend"?"Any day":"Weekend")}>Weekend</button><button className="pill" aria-pressed={free} onClick={()=>setFree(!free)}>Free</button>{(query||cat!=="All"||cost!=="Any"||day!=="Any day"||free)&&<button className="pill" onClick={()=>{setQuery("");setCat("All");setCost("Any");setDay("Any day");setFree(false);}}>Reset</button>}</div>}
 {tab==="Picks"&&<div className="scroll-panel">{picks.length?<div className="cards">{picks.map((e:Event)=>card(e))}</div>:<div className="empty"><Glyph kind="spark"/>Nothing strong matches these filters.</div>}</div>}
 {tab==="Calendar"&&<div className="calendar-layout"><div className="month-wrap"><div className="week-head">{["Sun","Mon","Tue","Wed","Thu","Fri","Sat"].map((d:string)=><span key={d}>{d}</span>)}</div><div className="month-grid" role="grid" aria-label={MONTHS[monthIndex]+" "+monthYear}>{cells.map((n:number,i:number)=>{if(n<1||n>daysInMonth)return <div key={i} className="day blank"/>;const d=month+"-"+String(n).padStart(2,"0");const os=occurrences.filter((o:{event:Event;date:string;time:string})=>o.date===d);return <button role="gridcell" className={"day "+(weekend(d)?"weekend":"evening")+(d===AS_OF?" today":"")} key={i} aria-pressed={chosenDay===d} aria-label={date(d)+", "+os.length+" listed sessions"} onClick={()=>setChosenDay(d)}><span className="day-num">{n}</span><span className="dots">{os.slice(0,5).map((o:{event:Event;date:string;time:string},j:number)=><span key={j} className="dot" title={o.event.name+" · "+clock(o.time)}/>)}</span>{os.length>0&&<span className="day-count">{os.length} {os.length===1?"session":"sessions"}</span>}</button>;})}</div></div><aside className="day-panel"><h3>{date(chosenDay)}</h3>{dayEvents.length?dayEvents.map((o:{event:Event;date:string;time:string},i:number)=><button className="day-event" key={o.event.id+i} onClick={()=>setSelected(o.event)}><span className="mini-glyph"><Glyph kind={o.event.category}/></span><span><strong>{o.event.name}</strong><small>{clock(o.time)} {TZ_LABEL} · {usd(price(o.event))}{(price(o.event)??0)>0?"+":""}</small></span></button>):<div className="empty"><Glyph kind="calendar" size={20}/>No listed events this day.</div>}</aside></div>}
 {tab==="Save for later"&&<><div className="section-head"><div><h2>Worth saving for</h2><div className="sub">{ANNUAL.length} annual experiences · swipe across months</div></div><div className="head-actions"><div className="search"><input aria-label="Search annual events" placeholder="Search the year ahead" value={query} onChange={(e:ChangeEvent<HTMLInputElement>)=>setQuery(e.target.value)}/></div><button className="pill" aria-pressed={free} onClick={()=>setFree(!free)}>Free</button></div></div><div className="timeline">{annualGroups.length===0&&<div className="empty"><Glyph kind="bookmark"/>No annual events match these filters.</div>}{annualGroups.map((k:string)=><section className="month-column" key={k}><div className="month-label">{groupLabel(k)}</div>{annualFiltered.filter((a:Annual)=>annualGroup(a)===k).sort((a:Annual,b:Annual)=>(a.date_start||"").localeCompare(b.date_start||"")).map((a:Annual)=><button key={a.id} className="annual-card" onClick={()=>setSelected(a)}><span className="mini-glyph"><Glyph kind={a.category}/></span><div><strong>{a.name}</strong><small>{a.category}</small><div className="annual-price">{range(a.price_min,a.price_max)}</div><small>{a.price_basis==="published"?"Published range":a.price_basis==="historical"?"Historical range":"Planning range"}</small></div></button>)}</section>)}</div></>}
 {tab==="History"&&<><div className="section-head"><h2>Your experiences</h2><button className="pill" onClick={()=>setHelp(true)}>How to give feedback</button></div><div className="scroll-panel">{LATEST.length?<div className="day-panel">{LATEST.map((h:HistoryEntry)=>{const ev=EVENTS.find((e:Event)=>e.id===h.event_id);return <button className="day-event" key={h.event_id+h.date} onClick={()=>ev&&setSelected(ev)}><span className="mini-glyph"><Glyph kind={ev?.category||"history"}/></span><span><strong>{ev?.name||h.event_name||h.event_id}</strong><small>{h.status}{h.worth_it?" · "+h.worth_it.replaceAll("_"," "):""} · {date(historyEventDate(h))}{h.decline_reason?" · "+h.decline_reason:""}{h.feedback_notes?" · "+h.feedback_notes:""}</small></span></button>;})}</div>:<div className="empty"><Glyph kind="history" size={32}/>Your first accept, decline or rating starts here.</div>}</div></>}
 {tab==="Budget"&&<><div className="section-head"><div><h2>Make room for the exceptional</h2><div className="sub">{BUDGET.budget_year_start?longDate(BUDGET.budget_year_start)+" – "+longDate(BUDGET.budget_year_end):"Budget year not set"} · {BUDGET.scope||"scope not set"}</div></div><span className="pill">{BUDGET.per_event_max!==null?usd(BUDGET.per_event_max)+" max / event":"No per-event max set"}</span></div><div className="budget-panel"><svg className="ring" viewBox="0 0 320 320" role="img" aria-label={TARGET!==null?usd(SPENT)+" spent of "+usd(TARGET)+"; "+usd(REMAINING)+" remaining":"Annual budget not set"}><circle cx="160" cy="160" r="126" fill="none" stroke={t.border.default} strokeWidth="16" strokeDasharray={BASELINE_KNOWN?undefined:"6 8"}/>{SPENT>0&&TARGET!==null&&TARGET>0&&<circle cx="160" cy="160" r="126" fill="none" stroke={t.dataviz.categorical[0]} strokeWidth="16" pathLength="100" strokeDasharray={Math.max(0,Math.min(100,SPENT/TARGET*100))+" 100"} transform="rotate(-90 160 160)" strokeLinecap="round"/>}<text x="160" y="135" textAnchor="middle" fill={t.text.secondary} style={{fontSize:12,fontFamily:t.font.family}}>{BASELINE_KNOWN?"BUDGET YEAR SPENT":"BASELINE NEEDED"}</text><text x="160" y="177" textAnchor="middle" fill={t.text.primary} style={{fontSize:40,fontWeight:600,fontFamily:t.font.family}}>{usd(SPENT)}</text><text x="160" y="206" textAnchor="middle" fill={t.text.secondary} style={{fontSize:14,fontFamily:t.font.family}}>{TARGET!==null?"of "+usd(TARGET):"no annual target set"}</text></svg><div className="budget-facts"><div><strong>{REMAINING!==null?usd(REMAINING):"—"}</strong><span>{REMAINING!==null&&REMAINING<0?"over budget":"remaining"}</span></div><div title={"As of "+longDate(AS_OF)+"; includes today through "+longDate(BUDGET.budget_year_end)+"."}><strong>{DAYS_LEFT!==null?DAYS_LEFT:"—"}</strong><span>days left · including today</span></div><div><strong>{MONTH_USED} / {CAP!==null?CAP:"∞"}</strong><span>{MONTHS[Number(AS_OF.slice(5,7))-1]} events{BUDGET.cap_counts_free_events===null?"":BUDGET.cap_counts_free_events?" · free events count":" · free events don't count"}</span>{CAP!==null&&<div className="budget-dots" role="img" aria-label={MONTH_USED+" of "+CAP+" monthly event slots used"}>{Array.from({length:CAP},(_:unknown,i:number)=><i key={i} className={"budget-dot"+(i<MONTH_USED?" used":"")}/>)}</div>}</div></div></div><div className="sub" style={{marginTop:12}}>Update the baseline, budget or cap in chat.</div></>}
 </main>
 <footer className="footer"><span>Snapshot {PAGE_DATA.as_of?date(PAGE_DATA.as_of):"—"} · {TZ_LABEL} · recommend only</span><span className="footer-extra">Accept / decline / feedback in chat; filters are temporary.</span><button onClick={()=>setHelp(true)}>Help</button></footer>
 {(selected||help)&&<div className="overlay" onClick={()=>{setSelected(null);setHelp(false);}}><div className="drawer" role="dialog" aria-modal="true" aria-labelledby="detail-title" ref={drawer} onClick={(e:{stopPropagation:()=>void})=>e.stopPropagation()} onKeyDown={keyTrap}><div className="drawer-top"><span>{help?"QUICK GUIDE":selectedEvent?selectedEvent.id:"ANNUAL WATCHLIST"}</span><button className="icon-button" aria-label="Close details" ref={closeButton} onClick={()=>{setSelected(null);setHelp(false);}}>×</button></div><div className="drawer-body">
 {help?<><div className="drawer-art"><Glyph kind="spark" size={64}/></div><h2 id="detail-title">Less planning. Better experiences.</h2><dl><dt>Choose</dt><dd>In chat: “Accept &lt;event id&gt;” or “Decline &lt;event id&gt; — reason”. Accept means interested, never registered.</dd><dt>Reflect</dt><dd>Afterward: event + Worth it / Mixed / Not worth it + actual ticket cost + one sentence.</dd><dt>Budget</dt><dd>{BUDGET.budget_year_start?longDate(BUDGET.budget_year_start)+"–"+longDate(BUDGET.budget_year_end):"Year not set"} · {TARGET!==null?usd(TARGET):"no target"} · {BASELINE_KNOWN?usd(BUDGET.baseline_spend)+" starting spend":"baseline needed"} · {BUDGET.per_event_max!==null?usd(BUDGET.per_event_max)+" maximum per event":"no per-event max"} · {CAP!==null?CAP+" accepted events per calendar month"+(BUDGET.cap_counts_free_events?", including free events":""):"no monthly cap"}.</dd><dt>Prices</dt><dd>Bargain's best-found price and source; check membership conditions, fees and availability in event details.</dd><dt>Calendar</dt><dd>Shading reflects your usual free time, not checked conflicts. Only recorded dates and sessions appear.</dd></dl><p>Opening a source never books, RSVPs or messages anyone. This Page is a snapshot; view controls save nothing.</p></>:selectedEvent?<><div className="drawer-art"><Glyph kind={selectedEvent.category} size={64}/></div><h2 id="detail-title">{selectedEvent.name}</h2><dl><dt>When</dt><dd>{date(selectedEvent.date)} · {clock(selectedEvent.time)}{selectedEvent.end?"–"+clock(selectedEvent.end):""} {TZ_LABEL}{selectedEvent.sessions&&selectedEvent.sessions.length>1&&<div>{selectedEvent.sessions.slice(1).map((s:{date:string;time:string})=><div key={s.date+s.time}>{date(s.date)} · {clock(s.time)} {TZ_LABEL}</div>)}</div>}</dd><dt>Where</dt><dd>{selectedEvent.venue}</dd><dt>Tickets</dt><dd>{range(selectedEvent.lo,selectedEvent.hi)} listed</dd>{selectedEvent.run&&<><dt>Run</dt><dd>{selectedEvent.run}</dd></>}{selectedEvent.availability&&<><dt>Availability</dt><dd>{selectedEvent.availability}</dd></>}{selectedEvent.on_call_ok!==undefined&&<><dt>On call</dt><dd>{selectedEvent.on_call_ok?"OK":"Not suitable"}</dd></>}</dl><div><div className="detail-label">Why it fits / trade-off</div><p>{selectedEvent.why}</p></div><div><div className="detail-label">{selectedEvent.pricing?priceLabel(selectedEvent):"Listed price · not bargain-checked"}</div><strong>{usd(price(selectedEvent))}{(selectedEvent.hi??0)>(selectedEvent.lo??0)&&!selectedEvent.pricing?"+":""}</strong><div style={{marginTop:8}}><a className="source-link" href={priceSource(selectedEvent)} target="_blank" rel="noreferrer">{selectedEvent.pricing?.best_source||new URL(priceSource(selectedEvent)).hostname} ↗</a></div>{selectedEvent.pricing?.conditions&&<div className="pricing-conditions">{selectedEvent.pricing.conditions}</div>}{pricingAlert(selectedEvent)&&<div className="pricing-conditions">{pricingAlert(selectedEvent)}</div>}{selectedEvent.pricing&&<div className="pricing-conditions" title={selectedEvent.pricing.notes||""}>{selectedEvent.pricing.confidence} · {selectedEvent.pricing.verified_at} {TZ_LABEL}</div>}</div><a className="primary-link" href={selectedEvent.url} target="_blank" rel="noreferrer">Open event details ↗</a><p>Decide in chat: Accept or Decline {selectedEvent.id}. No booking or RSVP.</p></>:selectedAnnual?<><div className="drawer-art"><Glyph kind={selectedAnnual.category} size={64}/></div><h2 id="detail-title">{selectedAnnual.name}</h2><dl><dt>When</dt><dd>{selectedAnnual.timing}</dd><dt>Dates</dt><dd>{selectedAnnual.dates_confirmed?"Confirmed in source snapshot":"Typical timing; unconfirmed"}</dd><dt>Tickets</dt><dd>{range(selectedAnnual.price_min,selectedAnnual.price_max)}</dd><dt>Type</dt><dd>{selectedAnnual.category}</dd><dt>Watch for</dt><dd>{selectedAnnual.worth_splurge?"Splurge candidate":selectedAnnual.best_free?"Strong free-value candidate":"Compare with your shortlist"}</dd></dl><p>{selectedAnnual.note||(selectedAnnual.price_basis==="published"?"Published range; fees extra. Verify before relying on it.":"Planning range, not a current quote. Prices, availability and inclusions need reconfirmation.")}</p><a className="primary-link" href={selectedAnnual.url} target="_blank" rel="noreferrer">Open official source ↗</a></>:null}
 </div></div></div>}
 </div>;
}
